/**
 * Static site generator for tiersaver.com.
 *
 *   node build/build.mjs           write the generated files into site/
 *   node build/build.mjs --check   write nothing; exit 1 if a committed file is out of date
 *
 * Input:  src/pages/**.html (front matter in a leading HTML comment, then the
 *         page body), src/partials/*.html, src/data.ts (numbers and snippets
 *         read from @tiersaver/core) and src/check/main.ts (browser script).
 * Output: one .html file per page, sitemap.xml and assets/list-check.js.
 *
 * Hand-maintained files that this script does not touch: _headers, robots.txt,
 * styleguide.html, styles/, fonts/ and the images in assets/.
 *
 * The build makes no network requests. Its output is deterministic: it
 * depends only on the sources, never on the clock or the machine.
 */
import { readFile, readdir, writeFile, mkdir } from "node:fs/promises";
import { dirname, join, relative, sep } from "node:path";
import { pathToFileURL } from "node:url";
import { build } from "esbuild";

import { SITE_DIR } from "./serve.mjs";

/** The site folder: web root and home of src/, build/ and test/. */
export { SITE_DIR };

const SRC_DIR = join(SITE_DIR, "src");
const PAGES_DIR = join(SRC_DIR, "pages");
const PARTIALS_DIR = join(SRC_DIR, "partials");

const SITE = {
  name: "TierSaver",
  origin: "https://tiersaver.com",
  tagline: "Automatic list hygiene for Klaviyo.",
  footerTagline: "Automatic list hygiene for Klaviyo, for Shopify brands.",
  legalEntity: "Digital Solvers LLC",
  copyrightYear: 2026,
  themeColor: "#eeeeec",
  cta: "Run my free list audit",
};

/** Sections of the site that group "doc" pages. */
const GROUPS = {
  help: { label: "Help center", parent: { href: "/help/", label: "Help center" } },
  guide: { label: "Guides", parent: { href: "/help/", label: "Help center" } },
  legal: { label: "Legal", parent: null },
};

/** How many help articles the footer lists (after "All help articles"). */
const FOOTER_HELP_LINKS = 5;

const BROWSER_SCRIPTS = {
  "list-check": {
    entry: join(SRC_DIR, "check", "main.ts"),
    banner:
      "/* TierSaver list health check. Generated by build/build.mjs from src/check and @tiersaver/core. Do not edit. */",
  },
};

// ---------------------------------------------------------------------------
// Sources
// ---------------------------------------------------------------------------

/** Escapes front matter text for use as element content or inside a double-quoted attribute. */
function escapeHtml(text) {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

async function walk(dir) {
  const out = [];
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await walk(path)));
    else out.push(path);
  }
  return out.sort();
}

/**
 * Splits a page source into its front matter and body. The front matter is a
 * leading HTML comment with one "key: value" per line.
 */
function parsePage(source, file) {
  const match = /^<!--\n([\s\S]*?)\n-->\n/.exec(source);
  if (!match) throw new Error(`${file}: missing front matter comment`);
  const meta = {};
  for (const line of match[1].split("\n")) {
    const colon = line.indexOf(":");
    if (colon < 1) throw new Error(`${file}: bad front matter line "${line}"`);
    meta[line.slice(0, colon).trim()] = line.slice(colon + 1).trim();
  }
  for (const key of ["title", "description", "layout"]) {
    if (!meta[key]) throw new Error(`${file}: front matter is missing "${key}"`);
  }
  if (meta.layout !== "landing" && meta.layout !== "doc") throw new Error(`${file}: unknown layout "${meta.layout}"`);
  if (meta.layout === "doc") {
    if (!GROUPS[meta.group]) throw new Error(`${file}: unknown group "${meta.group}"`);
    for (const key of ["nav", "lead", "order", "updated"]) {
      if (!meta[key]) throw new Error(`${file}: front matter is missing "${key}"`);
    }
  }
  if (meta.script && !BROWSER_SCRIPTS[meta.script]) throw new Error(`${file}: unknown script "${meta.script}"`);
  return { meta, body: source.slice(match[0].length) };
}

/** "help/undo.html" -> "/help/undo"; "help/index.html" -> "/help/"; "index.html" -> "/". */
function urlFor(path) {
  if (path === "index.html") return "/";
  if (path.endsWith("/index.html")) return `/${path.slice(0, -"index.html".length)}`;
  return `/${path.slice(0, -".html".length)}`;
}

async function loadPages() {
  const pages = [];
  for (const file of await walk(PAGES_DIR)) {
    if (!file.endsWith(".html")) continue;
    const path = relative(PAGES_DIR, file).split(sep).join("/");
    const { meta, body } = parsePage(await readFile(file, "utf8"), `src/pages/${path}`);
    pages.push({ path, url: urlFor(path), meta, body, order: Number(meta.order ?? 0) });
  }
  return pages;
}

async function loadPartials() {
  const partials = new Map();
  for (const file of await walk(PARTIALS_DIR)) {
    if (!file.endsWith(".html")) continue;
    partials.set(relative(PARTIALS_DIR, file).split(sep).join("/").slice(0, -".html".length), await readFile(file, "utf8"));
  }
  return partials;
}

/**
 * Bundles src/data.ts (TypeScript, imports @tiersaver/core) for Node and
 * returns the {{token}} values from siteData().
 */
async function loadSiteData() {
  const result = await build({
    entryPoints: [join(SRC_DIR, "data.ts")],
    absWorkingDir: SITE_DIR,
    bundle: true,
    format: "esm",
    platform: "node",
    write: false,
    logLevel: "silent",
  });
  const code = result.outputFiles[0].text;
  const module = await import(`data:text/javascript;base64,${Buffer.from(code).toString("base64")}`);
  return module.siteData();
}

async function bundleBrowserScript({ entry, banner }) {
  const result = await build({
    entryPoints: [entry],
    absWorkingDir: SITE_DIR,
    bundle: true,
    minify: true,
    format: "iife",
    platform: "browser",
    // Core freezes its tables; without this the bundle keeps every frozen
    // constant of core, including the ones the check never reads.
    pure: ["Object.freeze"],
    banner: { js: banner },
    write: false,
    logLevel: "silent",
  });
  return result.outputFiles[0].text;
}

// ---------------------------------------------------------------------------
// Templates
// ---------------------------------------------------------------------------

function docsIn(pages, group) {
  return pages.filter((p) => p.meta.layout === "doc" && p.meta.group === group).sort((a, b) => a.order - b.order);
}

function linkGrid(docs) {
  const items = docs.map(
    (p) => `        <li>
          <a class="link-card" href="${p.url}">
            <span class="link-card__title">${escapeHtml(p.meta.nav)}</span>
            <span class="link-card__text">${escapeHtml(p.meta.summary)}</span>
          </a>
        </li>`,
  );
  return `<ul class="link-grid">\n${items.join("\n")}\n      </ul>`;
}

/** Replaces {{> partial}} and {{token}} placeholders. Unknown names are errors. */
function fill(text, data, partials, file) {
  const withPartials = text.replace(/\{\{>\s*([\w-]+)\s*\}\}\n?/g, (_, name) => {
    const partial = partials.get(name);
    if (partial === undefined) throw new Error(`${file}: unknown partial "${name}"`);
    return partial;
  });
  return withPartials.replace(/\{\{\s*([\w.-]+)\s*\}\}/g, (_, key) => {
    if (!Object.hasOwn(data, key)) throw new Error(`${file}: unknown placeholder "{{${key}}}"`);
    return data[key];
  });
}

function head(page) {
  const { meta } = page;
  const title = page.path === "index.html" ? meta.title : `${meta.title} · ${SITE.name}`;
  const indexed = meta.sitemap !== "no";
  const canonical = `${SITE.origin}${page.url}`;
  const lines = [
    `<meta charset="utf-8">`,
    `<meta name="viewport" content="width=device-width, initial-scale=1">`,
    `<title>${escapeHtml(title)}</title>`,
    `<meta name="description" content="${escapeHtml(meta.description)}">`,
    indexed && `<link rel="canonical" href="${canonical}">`,
    `<meta name="theme-color" content="${SITE.themeColor}">`,
    `<meta property="og:site_name" content="${SITE.name}">`,
    `<meta property="og:type" content="${meta.layout === "doc" ? "article" : "website"}">`,
    `<meta property="og:title" content="${escapeHtml(meta.title)}">`,
    `<meta property="og:description" content="${escapeHtml(meta.description)}">`,
    indexed && `<meta property="og:url" content="${canonical}">`,
    `<meta property="og:image" content="${SITE.origin}/assets/og-image.png">`,
    `<meta property="og:image:width" content="1200">`,
    `<meta property="og:image:height" content="630">`,
    `<meta property="og:image:alt" content="${SITE.name}. ${SITE.tagline}">`,
    `<meta name="twitter:card" content="summary_large_image">`,
    `<link rel="icon" href="/assets/favicon.svg" type="image/svg+xml">`,
    `<link rel="icon" href="/assets/favicon-32.png" type="image/png" sizes="32x32">`,
    `<link rel="apple-touch-icon" href="/assets/apple-touch-icon.png">`,
    `<link rel="preload" href="/fonts/inter-tight-latin-300-normal.woff2" as="font" type="font/woff2" crossorigin>`,
    `<link rel="preload" href="/fonts/inter-tight-latin-400-normal.woff2" as="font" type="font/woff2" crossorigin>`,
    `<link rel="stylesheet" href="/styles/tokens.css">`,
    `<link rel="stylesheet" href="/styles/base.css">`,
    `<link rel="stylesheet" href="/styles/site.css">`,
    meta.script && `<script src="/assets/${meta.script}.js" defer></script>`,
  ];
  return lines
    .filter(Boolean)
    .map((line) => `  ${line}`)
    .join("\n");
}

/** The App Store listing does not exist yet: every CTA is a marked placeholder link. */
function cta(classes) {
  return `<a class="${classes}" href="#" data-todo="app-store-url">${SITE.cta}</a>`;
}

function header(page) {
  const helpCurrent = page.meta.group === "help" ? ' aria-current="page"' : "";
  return `  <a class="skip-link" href="#main">Skip to content</a>
  <header class="site-header">
    <div class="container site-header__inner">
      <a class="site-header__logo" href="/" aria-label="${SITE.name} home">
        <img src="/assets/logo.svg" alt="${SITE.name}" width="133" height="32">
      </a>
      <nav class="site-nav" aria-label="Main">
        <ul>
          <li><a href="/#how-it-works">How it works</a></li>
          <li><a href="/#list-check">List check</a></li>
          <li><a href="/#pricing">Pricing</a></li>
          <li><a href="/#faq">FAQ</a></li>
          <li><a href="/help/"${helpCurrent}>Help</a></li>
        </ul>
      </nav>
      ${cta("button button--small site-header__cta")}
    </div>
  </header>`;
}

function footer(pages, data) {
  const item = (href, label) => `            <li><a href="${href}">${escapeHtml(label)}</a></li>`;
  const column = (title, items) => `        <div class="site-footer__col">
          <h2 class="label">${title}</h2>
          <ul>
${items.join("\n")}
          </ul>
        </div>`;
  const columns = [
    column("Product", [
      item("/#how-it-works", "How it works"),
      item("/#list-check", "List health check"),
      item("/#pricing", "Pricing"),
      item("/#faq", "Questions"),
    ]),
    column("Help center", [
      item("/help/", "All help articles"),
      ...docsIn(pages, "help")
        .slice(0, FOOTER_HELP_LINKS)
        .map((p) => item(p.url, p.meta.nav)),
    ]),
    column(
      "Guides",
      docsIn(pages, "guide").map((p) => item(p.url, p.meta.nav)),
    ),
    column(
      "Legal",
      docsIn(pages, "legal").map((p) => item(p.url, p.meta.title)),
    ),
  ];
  return `  <footer class="site-footer">
    <div class="container">
      <div class="site-footer__top">
        <div class="site-footer__brand">
          <img src="/assets/logo.svg" alt="${SITE.name}" width="133" height="32">
          <p class="text-muted small">${SITE.footerTagline}</p>
        </div>
${columns.join("\n")}
      </div>
      <div class="site-footer__bottom">
        <p class="small text-muted">${SITE.name} is an independent product. It is not affiliated with, endorsed by or sponsored by Klaviyo, Inc. or Shopify Inc. Klaviyo and Shopify are trademarks of their respective owners and are used here only to describe what ${SITE.name} works with.</p>
        <p class="small text-muted">Klaviyo plan sizes and list prices mentioned on this site were read on ${data["prices.capturedOn"]} and may have changed. ${SITE.name} makes no promise about your Klaviyo plan or invoice.</p>
        <p class="small text-muted">© ${SITE.copyrightYear} ${SITE.legalEntity}. All rights reserved.</p>
      </div>
    </div>
  </footer>`;
}

function landingMain(body) {
  return `  <main id="main">
${body}  </main>`;
}

function docMain(page, pages, body) {
  const { meta } = page;
  const group = GROUPS[meta.group];
  const crumbs = [`<li><a href="/">Home</a></li>`];
  if (group.parent) crumbs.push(`<li><a href="${group.parent.href}">${group.parent.label}</a></li>`);
  crumbs.push(`<li aria-current="page">${escapeHtml(meta.nav)}</li>`);
  const draftBanner =
    meta.group === "legal"
      ? `    <div class="draft-banner" role="note">
      <p><strong>Draft, pending review.</strong> This document has not been reviewed by a lawyer, is not final and is not in effect. Text in <mark class="placeholder">[BRACKETS]</mark> is still to be filled in.</p>
    </div>
`
      : "";
  const siblings = docsIn(pages, meta.group).map((p) => {
    const current = p === page ? ' aria-current="page"' : "";
    return `            <li><a href="${p.url}"${current}>${escapeHtml(p.meta.nav)}</a></li>`;
  });
  return `  <main id="main" class="container doc">
${draftBanner}    <nav class="breadcrumb" aria-label="Breadcrumb">
      <ol>
${crumbs.map((c) => `          ${c}`).join("\n")}
      </ol>
    </nav>
    <div class="doc__grid">
      <article class="doc__article">
        <header class="doc__header">
          <p class="label">${escapeHtml(meta.kicker ?? group.label)}</p>
          <h1>${escapeHtml(meta.title)}</h1>
          <p class="lead">${escapeHtml(meta.lead)}</p>
          <p class="label doc__updated"><span>Last updated</span><span>${escapeHtml(meta.updated)}</span></p>
        </header>
        <div class="prose">
${body}        </div>
      </article>
      <aside class="doc__aside">
        <nav aria-label="${group.label}">
          <p class="label">${group.label}</p>
          <ul>
${siblings.join("\n")}
          </ul>
        </nav>
      </aside>
    </div>
  </main>`;
}

function renderPage(page, pages, data, partials) {
  const body = fill(page.body, data, partials, `src/pages/${page.path}`);
  const main = page.meta.layout === "doc" ? docMain(page, pages, body) : landingMain(body);
  return `<!doctype html>
<html lang="en">
<head>
${head(page)}
</head>
<body>
${header(page)}

${main}

${footer(pages, data)}
</body>
</html>
`;
}

function sitemap(pages) {
  const urls = pages
    .filter((p) => p.meta.sitemap !== "no")
    .map((p) => `${SITE.origin}${p.url}`)
    .sort();
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.map((url) => `  <url><loc>${url}</loc></url>`).join("\n")}
</urlset>
`;
}

// ---------------------------------------------------------------------------
// Entry points
// ---------------------------------------------------------------------------

/**
 * Generates every file of the site in memory.
 * @returns {Promise<Map<string, string>>} path relative to SITE_DIR (OS separators) -> content
 */
export async function generate() {
  const [pages, partials, coreData] = await Promise.all([loadPages(), loadPartials(), loadSiteData()]);
  const data = {
    ...coreData,
    "list.help": linkGrid(docsIn(pages, "help")),
    "list.guides": linkGrid(docsIn(pages, "guide")),
  };

  const out = new Map();
  for (const page of pages) out.set(join(...page.path.split("/")), renderPage(page, pages, data, partials));
  out.set("sitemap.xml", sitemap(pages));
  for (const [name, script] of Object.entries(BROWSER_SCRIPTS)) {
    out.set(join("assets", `${name}.js`), await bundleBrowserScript(script));
  }
  return out;
}

/** Paths whose committed content differs from what the sources generate. */
export async function drift(generated) {
  const stale = [];
  for (const [path, content] of generated) {
    const onDisk = await readFile(join(SITE_DIR, path), "utf8").catch(() => null);
    if (onDisk !== content) stale.push(path);
  }
  return stale;
}

async function main(argv) {
  const generated = await generate();
  const stale = await drift(generated);
  if (argv.includes("--check")) {
    if (stale.length === 0) {
      console.log(`site: ${generated.size} generated files are up to date`);
      return 0;
    }
    for (const path of stale) console.error(`out of date: ${path}`);
    console.error(`site: ${stale.length} of ${generated.size} generated files differ from the sources. Run "npm run build" in site/.`);
    return 1;
  }
  for (const path of stale) {
    await mkdir(dirname(join(SITE_DIR, path)), { recursive: true });
    await writeFile(join(SITE_DIR, path), generated.get(path));
    console.log(`wrote ${path}`);
  }
  console.log(`site: ${generated.size} files generated, ${stale.length} changed`);
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exitCode = await main(process.argv.slice(2));
}
